  static void CleanNode(Dictionary<string,object> node){object raw;if(node.TryGetValue("vmArgs",out raw)){if(raw is string||!(raw is IEnumerable)||raw is IDictionary)throw new IOException("Java 启动参数结构无法核实。");var items=((IEnumerable)raw).Cast<object>().ToArray();if(items.Any(v=>!(v is string)))throw new IOException("Java 启动参数结构无法核实。");node["vmArgs"]=items.Cast<string>().Where(v=>!Agent(v)).ToArray();}if(node.TryGetValue("windows",out raw)){var windows=raw as Dictionary<string,object>;if(windows==null)throw new IOException("Windows 启动分支无法核实。");foreach(var value in windows.Values){var branch=value as Dictionary<string,object>;if(branch==null)throw new IOException("Windows 启动分支无法核实。");CleanNode(branch);}}}
