  static byte[] CleanBat(byte[] bytes){Encoding encoding;byte[] bom;string text=Text(bytes,out encoding,out bom);if(Regex.IsMatch(text,@"(?i)-(javaagent|agentpath|agentlib):")&&Regex.IsMatch(text,@"(?m)^[ \t]*@?(?i:if|for|else)(?:\s|$)|[()^]"))throw new IOException("备用 BAT 含独立加载代理和复杂语法，需人工检查。");var result=new StringBuilder();foreach(Match match in Regex.Matches(text,@"[^\r\n]*(?:\r\n|\r|\n|$)")){string line=match.Value;if(line.Length==0)continue;string trim=line.TrimStart().TrimStart('@');if(trim.StartsWith("rem ",StringComparison.OrdinalIgnoreCase)||trim.StartsWith("::")||!Regex.IsMatch(line,@"(?i)-(javaagent|agentpath|agentlib):")){result.Append(line);continue;}if(line.IndexOfAny(new[]{'^','&','|','<','>','%','!','(',')'})>=0||Regex.IsMatch(trim,@"^(?i:echo|if|for|call|start|cmd)(?:\s|$)"))throw new IOException("备用 BAT 含独立加载代理和复杂语法，需人工检查。");var tokens=BuddyLaunchArguments.Tokens(line.TrimEnd('\r','\n'));var remove=tokens.Where(t=>Agent(t.Value)).ToArray();if(remove.Length==0)throw new IOException("备用 BAT 加载代理无法安全定位。");foreach(var token in remove.Reverse()){int end=token.End;while(end<line.Length&&line[end]!='\r'&&line[end]!='\n'&&char.IsWhiteSpace(line[end]))end++;line=line.Remove(token.Start,end-token.Start);}result.Append(line);}return bom.Concat(encoding.GetBytes(result.ToString())).ToArray();}
