  Plan Scan(){Ready();if(File.Exists(pending))throw new IOException("上次强制接管尚未恢复，请先检查恢复状态。");var plan=new Plan{Identity=env.Capture()};Identity(plan.Identity);if(env.Inspect(plan.Identity)!=BuddySteamState.Running)throw new IOException(Changed);if(BuddyTakeover.Pending(engine)){plan.Ordinary=BuddyTakeover.ReadForForce(engine,plan.Identity);plan.Locations.Add("终结已验证的普通接管恢复记录 · 保留原私人备份");}var options=plan.Identity.Options;
