  public object Preview(){var result=new PreviewResult();try{var plan=Scan();result.supported=true;result.requiresSteamExit=true;result.stamp=plan.Stamp;result.locations=plan.Locations.ToArray();result.unresolved=plan.Unresolved.Distinct().ToArray();result.warnings=new[]{"本次会备份并清空当前账号此游戏的全部 Steam 启动选项，正常退出并重新打开 Steam。","接管后从组件中心重新安装或启用；不会自动启用任何模组。"};result.message="强制接管会清空全部游戏启动选项并停用已确认的加载入口。";}catch(Exception error){result.message=error is IOException?error.Message:"无法核实强制接管范围，请刷新检查。";}return result;}
