  void BlockJava(Record r,Plan plan,CancellationToken cancel){using(var java=Java(plan.Identity,plan.CleanMain,r.id)){var expectedState=plan.Evidence;CheckEvidence(expectedState,java.TakeoverEvidence());Save(r,"java");foreach(string token in r.javaTokens){cancel.ThrowIfCancellationRequested();VerifyStopped(plan.Identity);var snapshot=java.CaptureTakeover();CheckEvidence(expectedState,snapshot.Evidence);var inventory=snapshot.Inventory;var row=inventory.rows.SingleOrDefault(v=>v.token==token);if(row==null)throw new IOException(Changed);if(row.javaBlocked)continue;if(!row.canBlock){plan.Unresolved.Add(row.name+" 的来源未核实，尚未屏蔽。");continue;}var before=snapshot.Evidence;var preview=(JavaComponents.PreviewResult)java.Preview(token,"block",inventory.stamp);if(!preview.supported)throw new IOException("Java 屏蔽预览已变化，请检查组件中心。");r.javaAttempted=true;Save(r,"javaWriting");var result=(JavaComponents.Result)java.Apply(preview.previewStamp,true,cancel);if(result.status!="completed"&&result.status!="unchanged")throw new IOException("一个 Java 屏蔽事务未完成，请检查恢复状态。");var receipt=java.TakeoverReceipts(r.id).SingleOrDefault(v=>v.id==result.receiptId);if(receipt!=null){var expected=new Dictionary<string,string>(before,StringComparer.OrdinalIgnoreCase);foreach(var entry in receipt.entries){if(expected.ContainsKey(Full(entry.target)))expected[Full(entry.target)]=entry.after;}var after=java.TakeoverEvidence();expected[java.TakeoverStorePath]=after[java.TakeoverStorePath];CheckEvidence(expected,after);expectedState=after;}Save(r,"java");}CheckEvidence(expectedState,java.TakeoverEvidence());}}
